import { defaultCombatModifiers, defaultEquipment, defaultEventLog, defaultInventory, defaultResourceMirror, defaultVitals } from "../components/player.js";
import type { CombatModifiers, Equipment, EventLog, Inventory, ResourceMirror, Vitals } from "../components/player.js";
import type { MonsterInstance, ScheduledEvent, World } from "../types/game.js";

export class GameSession {
  tickCount = 0;
  vitals: Vitals = defaultVitals();
  inventory: Inventory = defaultInventory();
  resources: ResourceMirror = defaultResourceMirror();
  equipment: Equipment = defaultEquipment();
  combat: CombatModifiers = defaultCombatModifiers();
  eventLog: EventLog = defaultEventLog();
  monsters: MonsterInstance[] = [];
  pendingEvents: ScheduledEvent[] = [];
  rngState = 1;
  saveCounter = 0;
  worldRef: World | null = null;

  reset(seed: number): void {
    this.tickCount = 0;
    this.vitals = defaultVitals(); this.inventory = defaultInventory();
    this.resources = defaultResourceMirror(); this.equipment = defaultEquipment();
    this.combat = defaultCombatModifiers(); this.eventLog = defaultEventLog();
    this.pendingEvents = []; this.saveCounter = 0; this.monsters.length = 0;
    this.rngState = seed >>> 0;
  }
}

export const session = new GameSession();
import { session } from "../runtime/session.js";
import type { GameSnapshot, LogEntry, MonsterInstance } from "../types/game.js";

export function snapshot(): GameSnapshot {
  const s = session;
  return {
    tickCount: s.tickCount,
    hp: s.vitals.hp,
    maxHp: s.vitals.maxHp,
    wood: s.resources.wood,
    stone: s.resources.stone,
    inventory: { ...s.inventory.items },
    equippedWeapon: s.equipment.weapon,
    attackBonus: s.combat.attackBonus,
    torchBuffTicks: s.combat.torchBuffTicks,
    alive: s.vitals.alive,
    log: s.eventLog.entries.slice(-20),
    monsters: s.monsters.map((monster) => ({ ...monster })),
    rngState: s.rngState,
  };
}

export function restore(raw: string, say: (message: string) => void): void {
  const d = JSON.parse(raw) as GameSnapshot;
  const s = session;
  s.tickCount = d.tickCount as number;
  s.vitals.hp = d.hp as number;
  s.vitals.maxHp = d.maxHp as number;
  s.resources.wood = d.wood as number;
  s.resources.stone = d.stone as number;
  s.inventory.items = d.inventory as typeof s.inventory.items;
  s.equipment.weapon = d.equippedWeapon as string;
  s.combat.attackBonus = d.attackBonus as number;
  s.combat.torchBuffTicks = d.torchBuffTicks as number;
  s.vitals.alive = d.alive as boolean;
  s.eventLog.entries = (d.log as LogEntry[]).map((entry) => ({ ...entry }));
  s.monsters.length = 0;
  for (const monster of d.monsters as MonsterInstance[]) s.monsters.push({ ...monster });
  s.rngState = d.rngState as number;
  say("save restored");
}

export function decideUseStorage(): boolean {
  return !!session.worldRef && session.worldRef.storage.get("ventralis:save") !== undefined;
}

export function persist(): void {
  const world = session.worldRef;
  if (!world || !decideUseStorage()) return;
  session.saveCounter += 1;
  world.storage.set(
    "ventralis:save",
    JSON.stringify({ ...snapshot(), savedAtTick: session.tickCount, saveCounter: session.saveCounter }),
  );
}
